-- ServicioPro: esquema inicial para una base de datos aislada. NO ejecutar sobre bases existentes de producción.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS sp_companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sp_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES sp_companies(id), email text NOT NULL, name text NOT NULL, role text NOT NULL CHECK (role IN ('admin','supervisor','technician')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,email), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS sp_customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES sp_companies(id), name text NOT NULL, phone text, email text, address text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS sp_work_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES sp_companies(id), customer_id uuid NOT NULL, technician_id uuid, title text NOT NULL, description text, status text NOT NULL DEFAULT 'new' CHECK (status IN ('new','quoted','scheduled','in_progress','completed','cancelled')), scheduled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,id), FOREIGN KEY(company_id,customer_id) REFERENCES sp_customers(company_id,id), FOREIGN KEY(company_id,technician_id) REFERENCES sp_users(company_id,id));
CREATE INDEX IF NOT EXISTS sp_orders_company_status ON sp_work_orders(company_id,status);
-- Pendiente: políticas RLS, autenticación y auditoría antes de cualquier uso real.
